INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.115.0',
  '2026-10-04',
  'Пульт ТВ: ссылки «где это ещё можно посмотреть»',
  E'Фильму, сериалу и папке можно добавить ссылки — на онлайн-кинотеатр, на страницу в Кинопоиске, на раздачу. Делается это в админке кнопкой «🔗» у строки; если ссылки есть, на экране самого сериала или фильма появляется кнопка «🔗 Ссылки».\n\nЗаголовок вводить не надо: агент берёт его из самой страницы. Набирать название на пульте мучительно, поэтому спрашивается только адрес — можно даже без «https://». Если страница закрыта от ботов и вместо названия отдаёт «Вы не робот?», в подпись пойдёт имя сайта, а не эта заглушка; поправить заголовок можно кнопкой «✏».\n\nНа экране ссылок адрес показан целиком — если приставка страницу не откроет, его можно набрать на телефоне. Ссылки переживают переименование в админке и не теряются, когда описание фильма ищется в интернете заново.',
  E'links.go, links.json в кэше агента. Ключ записи — тот же, что у избранного (favRef): путь, а у папки-подборки её id; renamePath двигает ссылки вместе с marks, frames и отметкой избранного.\n\nХранятся ОТДЕЛЬНО от «Инфо» намеренно: adminInfo с fetch переписывает .info.json целиком, и ссылки, поставленные руками, исчезли бы при первом же повторном поиске описания.\n\ncleanURL дописывает схему (без неё href считается относительным) и пускает только http(s) — javascript: и data: в href попасть не должны. Пустой заголовок добирается из <title> первых 64 КБ страницы; заслоны отдаются с кодом 200 и своим заголовком («Вы не робот?» у Кинопоиска, «Just a moment…» у Cloudflare), поэтому отсеиваются по reBlockTitle, иначе ими подписывалась бы ссылка. Не UTF-8 — тоже мимо: разбирать кодировки ради подписи незачем.\n\nЧисло ссылок едет в плитке (decorateTiles, там же где отметка избранного), поэтому кнопку видно и на экране сериала, который ничего дополнительно не запрашивает. В приложении ссылка открывается в той же вкладке: у вебвью может не быть новых окон, и target=_blank просто ничего не сделал бы.\n\nПроверено в браузере: добавление без схемы и с ней, подстановка заголовка из страницы (example.com), замена заслона Кинопоиска на имя сайта, правка и удаление, появление и исчезновение кнопки на экране сериала, фокус пультом на ссылке. Тесты links_test.go.'
);
-- +goose StatementEnd

